#include <bits/stdc++.h>
using namespace std;
#define ll long long

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	int t;
	cin >> t;
	while(t--){
	    int n;
	    cin >> n;
	    vector<int> v(n);
	    for(int i=0;i<n;i++){
	        cin >> v[i];
	    }
        vector<int> d(n);
        for(int i=0;i<n-1;i++){
            d[i]=abs(v[i]-v[i+1]);
        }
        d[n-1]=abs(v[0]-v[n-1]);
        sort(d.begin(),d.end());
        cout << d[n-2] << "\n";
	}

}
